/* Cadence's service worker — the app shell's offline story.
 *
 * The DATA layer is already offline-capable without any of this: Firestore's
 * persistentLocalCache (see src/firebase.js) keeps tasks, events and tags
 * readable and writable with no connection, and syncs when one comes back.
 * What was still missing is the shell — the HTML, JS and CSS that has to
 * load before that cache can be read at all. That is all this file does.
 *
 * Deliberately hand-written rather than generated by a plugin. A generated
 * service worker's main job is a precache manifest of build-hashed
 * filenames, and this needs no manifest: Vite's asset names already contain
 * a content hash, which makes them immutable and safe to cache on sight,
 * and the one file that ISN'T hashed — index.html — is exactly the file
 * that must never be served stale. Two rules, no build step, no dependency.
 *
 * Cache-busting is by CACHE version below. Bump it when a change here needs
 * to invalidate what previous versions stored; ordinary app deploys don't
 * need it, since the entries are either immutable or network-first.
 */

const CACHE = 'cadence-shell-v1'

/* Enough to render something useful on a cold, offline start. Kept to files
   whose paths are stable across builds — every hashed asset arrives through
   the runtime cache below instead, on its first successful load. */
const SEED = ['/', '/index.html', '/favicon.svg', '/manifest.webmanifest', '/icon-192.png']

/* CacheStorage is not guaranteed to be there.
 *
 * It can be missing or throw outright — a private window, a browser
 * configured to block site data, storage pressure, a corrupted profile.
 * Every cache call in this file goes through one of these two helpers so
 * that a storage failure degrades to "no offline support" and never to "the
 * app does not load": openCache resolves to null instead of rejecting, and
 * fromCache resolves to undefined, which every caller below reads as a miss
 * and answers from the network.
 *
 * This is not hypothetical defensiveness — it was found by running the built
 * app in a browser whose CacheStorage returned an internal error. The first
 * version of this file failed to install at all there, and its fetch handler
 * would have passed a rejected promise to respondWith, turning one broken
 * storage backend into a blank page.
 */
function openCache() {
  try {
    return caches.open(CACHE).catch(() => null)
  } catch {
    return Promise.resolve(null)
  }
}

function fromCache(request) {
  try {
    return caches.match(request).catch(() => undefined)
  } catch {
    return Promise.resolve(undefined)
  }
}

/** Best-effort write. Nothing waits on it, and nothing breaks if it fails. */
function put(request, response) {
  const copy = response.clone()
  openCache().then((cache) => cache?.put(request, copy)).catch(() => undefined)
}

self.addEventListener('install', (event) => {
  /* Seeded one at a time rather than with addAll, which would reject the
     whole install if any single request failed — one 404, or one flaky
     response on a bad connection, should not cost the worker its
     installation. The outer catch covers the same for storage itself: the
     seed is an optimisation for the first offline start, and the runtime
     cache below fills in regardless, so failing to write it is never a
     reason to refuse to install. */
  event.waitUntil(
    openCache()
      .then((cache) =>
        cache ? Promise.all(SEED.map((url) => cache.add(url).catch(() => undefined))) : undefined,
      )
      .catch(() => undefined),
  )
  // Don't sit in "waiting" behind the previous worker: there is one client
  // here (a personal app in one tab), so the usual reason to wait — other
  // tabs mid-session on the old assets — does not apply.
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))
      .catch(() => undefined)
      .then(() => self.clients.claim()),
  )
})

/** Whether a request is for one of Vite's content-hashed build outputs.
    Those can be cached on sight and served from cache forever, because a
    changed file arrives under a different name rather than as new bytes at
    the same one. */
function isHashedAsset(url) {
  return url.pathname.startsWith('/assets/')
}

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return

  const url = new URL(request.url)

  /* Only this origin. Firestore, Google Fonts and the auth endpoints all
     handle their own caching and consistency, and a service worker guessing
     on their behalf is how you end up serving a stale auth token or a
     half-synced write. */
  if (url.origin !== self.location.origin) return

  /* A navigation is network-first: index.html is the one unhashed file, so
     a cached copy pointing at last deploy's assets is exactly the failure
     to avoid. Offline, the cached shell is served instead — which is the
     whole point of installing this. */
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          if (response.ok) put('/index.html', response)
          return response
        })
        .catch(async () => (await fromCache('/index.html')) ?? (await fromCache('/')) ?? Response.error()),
    )
    return
  }

  if (isHashedAsset(url)) {
    event.respondWith(
      fromCache(request).then(
        (cached) =>
          cached ??
          fetch(request).then((response) => {
            /* Only a real, complete response is worth keeping. An opaque or
               error response cached here would be served back as the asset
               itself on every later load, turning one bad fetch into a
               permanently broken build. */
            if (response.ok && response.type === 'basic') put(request, response)
            return response
          }),
      ),
    )
    return
  }

  /* Everything else same-origin — icons, sounds, the manifest: try the
     network, fall back to whatever was stored. Stale-while-revalidate would
     be tempting here, but these are small and rarely change, and a fallback
     is all offline actually needs. */
  event.respondWith(
    fetch(request)
      .then((response) => {
        if (response.ok && response.type === 'basic') put(request, response)
        return response
      })
      .catch(async () => (await fromCache(request)) ?? Response.error()),
  )
})
